import axios from 'axios';
import { message } from 'antd';
import { t } from '../i18n';

const isDevelopment = process.env.NODE_ENV === 'development';
const defaultProdBase = `${window.location.protocol}//${window.location.hostname}:8068/api/local/`;
const baseURL = process.env.REACT_APP_LOCAL_API_BASE || (isDevelopment ? '/api/local/' : defaultProdBase);

const http = axios.create({
  baseURL,
  timeout: 300000,
});

http.defaults.headers.post['Content-Type'] = 'application/json;charset=UTF-8';

http.interceptors.response.use(
  (response) => {
    if (response.data && (response.data.code === 100 || response.data.code === 400)) {
      return response.data;
    }
    message.error((response.data && response.data.msg) || t('http.requestFailed'));
    return response.data;
  },
  (error) => {
    if (error.response && error.response.status) {
      return Promise.reject(error.response);
    }
    return Promise.reject(error.response);
  }
);

export default http;
